package org.circus.core;

import java.io.*;
import java.util.*;

/** Raw NAMES single authority, borrowed adapters and adjacent-owner aliases. */
public final class Pc1CatalogMemoryTests {
    private static int count;
    private static void check(boolean value,String why){count++;if(!value)throw new AssertionError(why);}
    private interface Work {void run()throws Exception;}
    private static byte[] bytes(String value){byte[] raw=new byte[value.length()/2];for(int n=0;n<raw.length;n++)raw[n]=(byte)Integer.parseInt(value.substring(n*2,n*2+2),16);return raw;}
    // BEGIN LOOKUP VECTORS
    private static final String[] LOOKUPS={
        "case|53544f72792e4d4553|73746f7279|1|0|0|4c4142454c30",
        "path|5359535c53746f72792e6d6573|73746f7279,7379735c73746f7279|2|0|1|4c4142454c31",
        "no_basename|53746f72792e6d6573|7379735c73746f7279|1|0|-1|",
        "first_dot|6469722e77697468646f745c73746f72792e6d6573|73746f7279,646972|2|0|1|4c4142454c31",
        "leading_dot|2e73746f7279|6f74686572,|2|0|1|4c4142454c31",
        "embedded_nul|41007461696c|61|1|0|0|4c4142454c30",
        "non_ascii|c04162|e06162,c06142|2|0|1|4c4142454c31",
        "zero_count|41||0|0|-1|",
        "negative_count|41||-1|0|-1|",
        "first_match|41|61,41|2|0|0|4c4142454c30",
        "label_crosses_row|6669727374|6669727374,4e455854|2|1|0|4141414141414141414141414141414141414141414141414141414141414141414141414141414141414141414141414141414141414141414141414e455854"
    };
    // END LOOKUP VECTORS
    private static void reject(Work work,String text)throws Exception{boolean bad=false;try{work.run();}catch(IOException expected){bad=String.valueOf(expected.getMessage()).contains(text);}check(bad,"precise "+text);}
    private static final class Fixture {
        final byte[] settings=new byte[Pc1NativeSettings.SIZE],font=new byte[4],beforeCg=new byte[128],beforeMusic=new byte[8];final Pc1NativeMemory bus;final Pc1CatalogMemory memory;
        Fixture()throws IOException{bus=new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int at){return settings[at]&255;}public void write(int at,int value){settings[at]=(byte)value;}});memory=new Pc1CatalogMemory(bus);bind(0x971764,font);bind(0x9bb488,beforeCg);bind(0xbb84b8,beforeMusic);}
        void bind(int address,byte[] raw)throws IOException{bus.bind(address,raw.length,new Pc1NativeMemory.Region(){public int read(int at){return raw[at]&255;}public void write(int at,int value){raw[at]=(byte)value;}});}
        void cstring(int address,String text)throws IOException{byte[] raw=text.getBytes("US-ASCII");for(int n=0;n<raw.length;n++)bus.writeAddress(address+n,raw[n]);bus.writeAddress(address+raw.length,0);}
        byte[] save()throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();memory.save(new DataOutputStream(out));return out.toByteArray();}
    }
    public static int run()throws Exception{
        count=0;Fixture f=new Fixture();Pc1CatalogMemory m=f.memory;check(f.save().length==294860,"P1N1 owns exactly reviewed294856 raw bytes and magic");check(m.count(Pc1CatalogMemory.Table.SYSTEM)==6,"six system rows are native constant, not an invented global count");for(Pc1CatalogMemory.Table table:Pc1CatalogMemory.Table.values()){if(table!=Pc1CatalogMemory.Table.SYSTEM)check(m.count(table)==0,"BSS initial count "+table);check(m.read(table.address)==0&&m.read(table.address+table.knownBytes-1)==0,"known BSS extent "+table);}
        check(new String(m.cstring(Pc1CatalogMemory.CATEGORY),"US-ASCII").equals("DAT")&&new String(m.cstring(Pc1CatalogMemory.NAME),"US-ASCII").equals("names")&&new String(m.cstring(Pc1CatalogMemory.EXTENSION),"US-ASCII").equals(".dat"),"exact mutable PE path literals");
        m.dword(Pc1CatalogMemory.MUSIC_COUNT,1);m.dword(Pc1CatalogMemory.SOUND_COUNT,1);m.dword(Pc1CatalogMemory.SCENARIO_COUNT,1);f.cstring(Pc1CatalogMemory.Table.MUSIC.address,"track0");f.cstring(Pc1CatalogMemory.Table.MUSIC.address+128,"Title0");m.dword(Pc1CatalogMemory.Table.MUSIC.address+188,7);f.cstring(Pc1CatalogMemory.Table.SOUND.address,"se0");m.dword(Pc1CatalogMemory.Table.SOUND.address+128,-3);f.cstring(Pc1CatalogMemory.Table.SCENARIO.address,"story0");f.cstring(Pc1CatalogMemory.Table.SCENARIO.address+128,"Scene0");Pc1Audio.Catalog audio=m.audioCatalog();Pc1Audio.Entry old=audio.music(0);check(old.gainTrim==7&&Arrays.equals(old.rawName(),"track0".getBytes("US-ASCII")),"audio adapter reads music name and native188 trim");check(audio.sound(0).gainTrim==-3,"SE128 trim preserves signed DWORD");m.dword(Pc1CatalogMemory.Table.MUSIC.address+188,9);m.write(Pc1CatalogMemory.Table.MUSIC.address,'X');check(audio.music(0).gainTrim==9&&audio.music(0).rawName()[0]=='X'&&old.rawName()[0]=='t',"adapter rereads same canonical bytes on each call, without a cached table");m.dword(Pc1CatalogMemory.MUSIC_COUNT,0xdeadbeef);check(audio.musicCount()==0xdeadbeef,"raw counts admit every DWORD; adapter never normalizes or clips");m.dword(Pc1CatalogMemory.MUSIC_COUNT,1);
        byte[] given={'N'},family={'F'};final int[] variable={12};Pc1TextExpander.Context text=m.textContext(new Pc1CatalogMemory.LiveText(){public byte[] givenName(){return given.clone();}public byte[] familyName(){return family.clone();}public int read(int bank,int index){return variable[0];}});check(Arrays.equals(Pc1TextExpander.expand("$n/$f/$m0/$t0/$0,1".getBytes("US-ASCII"),text),"N/F/Title0/Scene0/12".getBytes("US-ASCII")),"same catalog labels combine with live names/variables");given[0]='G';variable[0]=34;f.cstring(Pc1CatalogMemory.Table.SCENARIO.address+128,"NewScene");check(Arrays.equals(Pc1TextExpander.expand("$n/$t0/$0,1".getBytes("US-ASCII"),text),"G/NewScene/34".getBytes("US-ASCII")),"text adapter sees later edits to every actual owner");
        for(int at=128;at<205;at++)m.write(Pc1CatalogMemory.Table.MUSIC.address+at,'A');m.write(Pc1CatalogMemory.Table.MUSIC.address+205,0);check(m.label(Pc1CatalogMemory.Table.MUSIC,0).length==77&&text.musicLabel(0).length==77,"label C string crosses trim and next row rather than clipping at64");check(audio.music(0).gainTrim==0x41414141&&audio.music(1).rawName().length==13,"raw label edits alias trim/next name and raw adapter has no invented count bound");for(int n=0;n<128;n++)m.write(Pc1CatalogMemory.Table.SCENARIO.address+n,'B');f.cstring(Pc1CatalogMemory.Table.SCENARIO.address+128,"label");check(m.name(Pc1CatalogMemory.Table.SCENARIO,0).length==133,"unterminated128 name reads known label bytes like native strcpy");
        f.font[0]=28;check(Arrays.equals(m.name(Pc1CatalogMemory.Table.SYSTEM,6),new byte[]{28}),"system row6 address aliases existing next FONT owner, not synthetic empty table");f.cstring(0x9bb488,"previous");check(Arrays.equals(m.name(Pc1CatalogMemory.Table.CG,-1),"previous".getBytes("US-ASCII")),"negative CG raw address uses real preceding known owner");f.cstring(0xbb84b8,"prior");check(Arrays.equals(m.name(Pc1CatalogMemory.Table.MUSIC,-1),"prior".getBytes("US-ASCII")),"negative music address does not invent zero or reject known neighbor");check(Arrays.equals(m.name(Pc1CatalogMemory.Table.MUSIC,Integer.MIN_VALUE),m.name(Pc1CatalogMemory.Table.MUSIC,0)),"native32-bit stride multiplication wraps before owner resolution");reject(()->m.read(0xbbaaf8),"unowned neighboring memory");reject(()->m.read(0xbc12c8),"unowned neighboring memory");reject(()->m.read(0x9a0778),"unowned neighboring memory");
        m.dword(Pc1CatalogMemory.CG_COUNT,1);f.cstring(Pc1CatalogMemory.Table.CG.address,"CG_TEST");Pc1CgVisit.visit("cg_test.CRX".getBytes("US-ASCII"),m.cgCatalog(),(index,value)->f.bus.writeAddress(Pc1CgVisit.CG+index,value));check(f.settings[Pc1NativeSettings.CG_OFFSET]==1,"CG facade writes same system.dat bytes, not catalog-local flags");m.dword(Pc1CatalogMemory.SCENARIO_COUNT,2);f.cstring(Pc1CatalogMemory.Table.SCENARIO.address,"PATH\\STORY");f.cstring(Pc1CatalogMemory.Table.SCENARIO.address+188,"DIR");check(m.findScenario("path\\story.MES".getBytes("US-ASCII"))==0&&m.findScenario("STORY.MES".getBytes("US-ASCII"))==-1,"scenario lookup compares full raw path with ASCII fold, no basename normalization");check(m.findScenario("dir.withdot\\other.mes".getBytes("US-ASCII"))==1,"scenario lookup uses first dot before a later separator");m.dword(Pc1CatalogMemory.CRT_LOCALE,1);reject(()->Pc1CgVisit.visit("CG_TEST".getBytes("US-ASCII"),m.cgCatalog(),(i,v)->{}),"42534C");reject(()->m.findScenario(new byte[0]),"42534C");m.dword(Pc1CatalogMemory.SCENARIO_COUNT,-1);check(m.findScenario(new byte[0])==-1,"nonpositive count avoids even CRT locale read like native");
        byte[] saved=f.save();Fixture next=new Fixture();next.memory.restore(Pc1CatalogMemory.loadImage(new DataInputStream(new ByteArrayInputStream(saved))));check(Arrays.equals(saved,next.save())&&next.memory.audioCatalog().music(0).gainTrim==0x41414141,"P1N1 keeps same canonical data and adapters after restore");byte[] image=Pc1CatalogMemory.loadImage(new DataInputStream(new ByteArrayInputStream(saved)));next.memory.restore(image);Arrays.fill(image,(byte)0);check(Arrays.equals(saved,next.save()),"restore copies owned image without caller alias");byte[] before=next.save();reject(()->next.memory.restore(new byte[1]),"size");check(Arrays.equals(before,next.save()),"bad image rejected before any publication");byte[] broken=saved.clone();broken[0]^=1;reject(()->Pc1CatalogMemory.loadImage(new DataInputStream(new ByteArrayInputStream(broken))),"format");reject(()->Pc1CatalogMemory.loadImage(new DataInputStream(new ByteArrayInputStream(Arrays.copyOf(saved,20)))),"");check(Arrays.equals(before,next.save()),"truncated decode cannot partially replace live catalog");
        check(LOOKUPS.length==11,"all native41AEA0 lookup/label programs");for(String vector:LOOKUPS){String[] fields=vector.split("\\|",-1);Fixture nativeCase=new Fixture();Pc1CatalogMemory target=nativeCase.memory;target.dword(Pc1CatalogMemory.SCENARIO_COUNT,Integer.parseInt(fields[3]));String[] rows=fields[2].isEmpty()?new String[0]:fields[2].split(",",-1);for(int n=0;n<rows.length;n++){byte[] raw=bytes(rows[n]);int address=Pc1CatalogMemory.Table.SCENARIO.address+n*188;for(int p=0;p<raw.length;p++)target.write(address+p,raw[p]);target.write(address+raw.length,0);nativeCase.cstring(address+128,"LABEL"+n);}if(fields[4].equals("1"))for(int n=0;n<60;n++)target.write(Pc1CatalogMemory.Table.SCENARIO.address+128+n,'A');byte[] beforeLookup=nativeCase.save();int index=target.findScenario(bytes(fields[1]));check(index==Integer.parseInt(fields[5]),fields[0]+" raw matching index inferred from original AL result");if(index>=0)check(Arrays.equals(target.label(Pc1CatalogMemory.Table.SCENARIO,index),bytes(fields[6])),fields[0]+" label bytes equal native frame-copy source, including cross-row C string");check(Arrays.equals(beforeLookup,nativeCase.save())&&Arrays.equals(nativeCase.settings,new byte[Pc1NativeSettings.SIZE]),"readonly lookup leaves frame/settings side effects to actual caller");}
        return count;
    }
    public static void main(String[] args)throws Exception{System.out.println("Pc1CatalogMemoryTests assertions: "+run());}
}
